import{_t as e,it as t,n,rt as r}from"./chunks/framework.B5d4da8a.js";var i=JSON.parse(`{"title":"The substrate-free kernel","description":"","frontmatter":{},"headers":[],"relativePath":"gamekit/explanation/the-kernel.md","filePath":"vendored/gamekit/explanation/the-kernel.md"}`),a={name:`gamekit/explanation/the-kernel.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="the-substrate-free-kernel" tabindex="-1">The substrate-free kernel <a class="header-anchor" href="#the-substrate-free-kernel" aria-label="Permalink to “The substrate-free kernel”">​</a></h1><p>The game kernel knows nothing about e-graphs, tensors, or laws. That is a <em>contract</em>, not an accident: <code>gamekit.engine</code>, <code>gamekit.scoring</code>, <code>gamekit.calibrate</code>, <code>gamekit.advantage</code>, <code>gamekit.gamedata</code>, and <code>gamekit.players</code> import nothing outside the stdlib — a <code>gamekit ⊥ eqsat</code> edge enforced by the repo&#39;s import-linter contract.</p><h2 id="why-the-wall-exists" tabindex="-1">Why the wall exists <a class="header-anchor" href="#why-the-wall-exists" aria-label="Permalink to “Why the wall exists”">​</a></h2><ul><li><strong>A board is a protocol, not a library.</strong> <code>observe() -&gt; state</code> and <code>step(action) -&gt; (state, report)</code> is all the drivers need. Anything with two methods can be a board — including a hand-rolled toy that exercises every driver path in the kernel&#39;s own suite.</li><li><strong>Players bind the domain lazily.</strong> Each player folder ships a <code>make</code> arm factory that imports <code>mlopt_discovery</code>/domain machinery <em>inside</em> the factory — so <code>import gamekit.players</code> stays stdlib-only, and in this repo (where no domain substrate is installed) the factories decline honestly instead of failing at import.</li><li><strong><code>register_player(spec, make)</code> is the plugin seam.</strong> A downstream domain seats its boards through the registry: a fresh name supplies <code>make</code>; a name matching the shipped roster unions <code>boards</code> into the shipped seat.</li></ul><h2 id="the-referee-seam" tabindex="-1">The referee seam <a class="header-anchor" href="#the-referee-seam" aria-label="Permalink to “The referee seam”">​</a></h2><p>The split that keeps the game honest runs through gamekit&#39;s edge:</p><ul><li><strong>the value spec is gamekit&#39;s</strong> — <code>ScoreGate</code>/<code>ScoringSpec</code> declare the axes and thresholds (speed, memory, launch, params, win-rate) as <em>data</em>; <code>score(spec, measured)</code> consumes a plain <code>Mapping[str, float]</code> and returns gates cleared, the weighted value, and the axes the measurement lacked;</li><li><strong>the measurement is the gauntlet&#39;s</strong> — the measured numbers come from the admission machinery on the substrate/domain side (<a href="/docs/graphopt/explanation/the-gauntlet.html">the gauntlet</a>).</li></ul><p>The two sides meet only through that mapping: measurement code never imports the scoring module, and the scoring module imports no measurement machinery. Calibration (<code>gamekit.calibrate</code> — Platt and isotonic fits plus metrics) tunes <em>scores</em>, never verdicts.</p><h2 id="where-the-rest-lives" tabindex="-1">Where the rest lives <a class="header-anchor" href="#where-the-rest-lives" aria-label="Permalink to “Where the rest lives”">​</a></h2><p>The episode machinery, the player roster, and the measured records are in <a href="./../reference/frozen-api.html">the reference</a>; the cross-cutting narrative — why a game at all, the learned-policy loop, the meta-game — is <a href="/docs/graphopt/explanation/the-game.html">the game</a> on the graphopt side.</p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};